import{_ as l,o as i,c as r,a2 as a}from"./chunks/framework.aJDz64y9.js";const c=JSON.parse('{"title":"Квартирные кражи","description":"","frontmatter":{},"headers":[],"relativePath":"crime/burglary.md","filePath":"crime/burglary.md","lastUpdated":1794540927000}'),e={name:"crime/burglary.md"};function d(o,t,n,s,h,g){return i(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="квартирные-кражи" tabindex="-1">Квартирные кражи <a class="header-anchor" href="#квартирные-кражи" aria-label="Permalink to &quot;Квартирные кражи&quot;">​</a></h1><p>Кража из дома — тихая работа на 1–4 человек: главный ресурс здесь шум, а добыча — только то, что успели физически вынести до возвращения жильцов.</p><h2 id="какие-дома" tabindex="-1">Какие дома <a class="header-anchor" href="#какие-дома" aria-label="Permalink to &quot;Какие дома&quot;">​</a></h2><p>Основной контент — дома NPC: адрес берётся из пула, жильцы и содержимое создаются под каждую наводку. Дома игроков подключаются на последнем этапе и только с защитой владельца.</p><table tabindex="0"><thead><tr><th>Ступень</th><th>Где</th><th>Защита</th><th>Добыча</th><th>Команда</th></tr></thead><tbody><tr><td>1</td><td>Трейлеры и дешёвые квартиры: Сэнди-Шорс, юг Лос-Сантоса</td><td>Простой замок</td><td>Наличные, бытовая техника, мелочь</td><td>1–2</td></tr><tr><td>2</td><td>Средний класс: Миррор-Парк, Веспуччи</td><td>Замок сложнее, у части домов сигнализация или собака</td><td>Техника, украшения, небольшой сейф</td><td>2–3</td></tr><tr><td>3</td><td>Особняки: Вайнвуд-Хиллз, Рокфорд-Хиллз</td><td>Сигнализация, камеры, сейф, иногда охрана</td><td>Картины, драгоценности, сейф целиком</td><td>3–4</td></tr></tbody></table><h2 id="этапы" tabindex="-1">Этапы <a class="header-anchor" href="#этапы" aria-label="Permalink to &quot;Этапы&quot;">​</a></h2><ol><li><strong>Наводка.</strong> Адрес добывают одним из трёх способов. <ul><li>Наводчик-NPC в баре продаёт адрес. Чем дороже, тем точнее: ступень, распорядок жильцов, наличие сигнализации.</li><li>Своя разведка с улицы биноклем или камерой. Видны свет в окнах, машина у дома, наклейка охранной фирмы, камера над дверью, собака.</li><li>Игроки легальных работ. Курьер, таксист, электрик или уборщик во время смены иногда получает предмет «заметка о доме»: адрес и наблюдение вроде «днём пусто, в гостиной большой телевизор». Заметку можно продать.</li><li>Наводка устаревает за несколько часов, и продавец может сбыть её двум командам сразу.</li></ul></li><li><strong>Подготовка.</strong> Команда выбирает время, машину и состав. Ночью меньше свидетелей, но жильцы дома и спят. Днём дом чаще пуст, но улицу видят соседи; рабочая форма и фургон с логотипом снижают их подозрение.</li><li><strong>Проникновение.</strong> У дома несколько входов: парадная и задняя двери, окно, гараж. <ul><li>Отмычка: мини-игра на замок. Ошибка даёт шум и может сломать отмычку.</li><li>Фомка: быстро и громко, остаётся след взлома.</li><li>Стеклорез: окно без шума, но медленно.</li><li>Сигнализация на ступенях 2–3: после входа есть 30–45 секунд, чтобы технарь нашёл панель и отключил её мини-игрой. Глушилка добавляет время. Щиток снаружи можно обесточить заранее, но тогда в доме темно, а свет фонарей виден с улицы.</li></ul></li><li><strong>Добыча.</strong> Внутри всё решает шкала шума. <ul><li>Шумят бег, обычный шаг, обыск, уроненная вещь, тележка и голос. Громкость голосового чата идёт в шкалу, поэтому в спящем доме приходится шептать.</li><li>Пороги шкалы: залаяла собака, проснулись жильцы, ушёл звонок в полицию. Проснувшийся жилец убегает и звонит или достаёт оружие. Его можно связать, но это уже разбой и другая статья.</li><li>Обыск ящиков и шкафов: содержимое проявляется по одному предмету за 0,5–1,5 секунды. Игрок сам решает, досматривать контейнер или идти дальше.</li><li>Запертое — шкатулка, ящик стола, сейф — требует инструмента и мини-игры. Небольшой сейф можно вывезти целиком на тележке.</li><li>Крупные вещи — телевизор, компьютер, картину — несут в руках к машине по одной.</li><li>Время поджимают три вещи: жильцы возвращаются по распорядку, подозрение соседей растёт, пока фургон стоит у дома, и по району ходит патруль. Наблюдатель снаружи следит за улицей.</li></ul></li><li><strong>Отход.</strong> Груз в багажнике виден при досмотре, поэтому маршрут и спокойная езда важнее скорости. Добычу везут в гараж остывать, а не сразу к скупщику.</li><li><strong>Сбыт.</strong> Вещи уходят по каналам из раздела <a href="./systems#скупка">«Скупка»</a>. Вывезенный сейф вскрывает мастер с дрелью за долю.</li></ol><p>В одной краже участвуют до шести живых контрагентов: продавец наводки, мастер инструментов, напарники, полиция, мастер по сейфам и скупщик.</p><h2 id="дома-игроков" tabindex="-1">Дома игроков <a class="header-anchor" href="#дома-игроков" aria-label="Permalink to &quot;Дома игроков&quot;">​</a></h2><p>Кража у игрока должна быть событием, а не обнулением, поэтому владельца защищают пять правил.</p><ul><li><strong>Потолок ущерба.</strong> Украсть можно только из открытого хранения и не больше трети его ценности. Купленный сейф защищает главное: он вскрывается инструментом третьей ступени, долго и громко.</li><li><strong>Пауза.</strong> После кражи дом закрыт для повторной на 5–7 дней.</li><li><strong>Защита за деньги.</strong> Сигнализация, камеры с уведомлением на телефон, усиленная дверь, собака и сейф покупаются и обслуживаются.</li><li><strong>Страховка.</strong> Сейчас её на сервере нет, поэтому она вводится вместе с этим этапом: еженедельный взнос, возврат части стоимости украденного, потолок выплат. Пары «вор — владелец» пишутся в журнал, чтобы ловить сговор.</li><li><strong>Живая встреча.</strong> Владелец в сети получает сигнал от своей сигнализации и может успеть вернуться. Заявление в полицию открывает дело с уликами.</li></ul>',11)])])}const _=l(e,[["render",d]]);export{c as __pageData,_ as default};
